package com.infoviaan.basic.SwitchCase;

public class SwitchIdConfirm {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int id = 101;
		
		switch(id) {
		case 101:
			System.out.println("Confirm");
			break;
		case 102:
			System.out.println("Confirm");
			break;
		case 103:
			System.out.println("Confirm");
			break;
		default:
			System.out.println("Invalid Id");
		}
	}

}
